insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Aux Petits Oignons — recette originale', now()
from (values
  ('curry-cabillaud-coco-epinards', 'Curry de cabillaud au lait de coco et épinards', 'Des morceaux de cabillaud pochés doucement dans une sauce au lait de coco, tomate et curry, avec des épinards qui fondent au dernier moment. Un curry doux et rapide, servi avec du riz basmati.', 'Se garde 2 jours au réfrigérateur. Réchauffer à feu doux à couvert, sans faire bouillir pour garder le poisson tendre. Ne se congèle pas bien.', 4, 15, 20, array['plat', 'poele']::text[]),
  ('parmentier-cabillaud', 'Parmentier de cabillaud', 'Du cabillaud effeuillé, poché dans le lait avec de l''ail, sous une purée de pommes de terre gratinée. Une façon douce de faire aimer le poisson, qui se prépare à l''avance et se réchauffe très bien.', 'Se garde 3 jours au réfrigérateur et se congèle 2 mois. Réchauffer 20 minutes au four à 180 °C, couvert.', 4, 25, 45, array['plat', 'four', 'batch-cooking']::text[]),
  ('spaghetti-sardines-citron', 'Spaghetti aux sardines, citron et chapelure dorée', 'Des spaghetti enrobés d''huile d''olive à l''ail, de sardines en boîte émiettées et de zeste de citron, avec une chapelure dorée qui croustille. Un plat de placard économique, plein de goût, prêt en vingt minutes.', 'Meilleur tout juste préparé : la chapelure ramollit. Les pâtes se gardent 1 jour au réfrigérateur ; les réchauffer à la poêle avec un filet d''huile.', 4, 10, 15, array['plat', 'poele', 'economique']::text[]),
  ('saumon-patate-douce-epinards', 'Pavés de saumon, patate douce rôtie et épinards', 'Des pavés de saumon cuits au four sur une plaque de patates douces rôties au paprika, avec des épinards sautés à l''ail. Un plat complet et coloré, presque sans vaisselle.', 'Se garde 2 jours au réfrigérateur. Se mange froid, émietté en salade, ou réchauffé doucement au four à 150 °C. Ne se congèle pas.', 4, 15, 30, array['plat', 'four']::text[]),
  ('saumon-lentilles-vertes', 'Saumon sur lit de lentilles vertes à la moutarde', 'Des lentilles vertes mijotées avec carotte et échalote, liées d''une vinaigrette tiède à la moutarde, et un pavé de saumon poêlé côté peau jusqu''à ce qu''elle croustille. Un plat de bistrot simple et très complet.', 'Les lentilles se gardent 4 jours au réfrigérateur et se congèlent 3 mois. Le saumon cuit se garde 2 jours et se mange froid ou tiède.', 4, 15, 30, array['plat', 'poele']::text[]),
  ('cabillaud-sauce-vierge-quinoa', 'Cabillaud, sauce vierge et quinoa', 'Des dos de cabillaud cuits à la poêle, nappés d''une sauce vierge crue de tomates, olives, basilic et citron, avec du quinoa. Léger et frais, avec les tomates de fin d''été.', 'Se garde 2 jours au réfrigérateur, la sauce vierge à part. Le quinoa et le poisson se mangent aussi froids, en salade.', 4, 20, 20, array['plat', 'poele']::text[]),
  ('salade-thon-haricots-blancs', 'Salade de haricots blancs, thon et oignon rouge', 'Une salade de placard à l''italienne : haricots blancs, thon, oignon rouge, tomates et persil, dans une vinaigrette au vinaigre. Prête en dix minutes sans rien cuire, elle fait un repas complet.', 'Se garde 2 jours au réfrigérateur, couverte. Les tomates rendent un peu d''eau : remuer avant de servir. Ne se congèle pas.', 4, 15, 0, array['salade', 'sans-cuisson', 'economique']::text[]),
  ('quiche-saumon-poireaux', 'Quiche au saumon et aux poireaux', 'Une quiche fondante aux poireaux étuvés au beurre et au saumon, dans une pâte brisée bien croustillante. Elle se prépare à l''avance et se mange chaude, tiède ou froide, avec une salade verte.', 'Se garde 3 jours au réfrigérateur. Réchauffer 10 minutes au four à 160 °C pour retrouver le croustillant. Se congèle 2 mois, en parts.', 6, 25, 40, array['plat', 'four']::text[]),
  ('pad-thai-crevettes', 'Nouilles sautées aux crevettes et cacahuètes', 'Des nouilles de riz sautées au wok avec des crevettes, des œufs et des carottes, dans une sauce sucrée-salée au citron vert, et parsemées de cacahuètes concassées. Inspiré du pad thaï, prêt en vingt-cinq minutes.', 'Se garde 2 jours au réfrigérateur. Réchauffer à la poêle avec un filet d''eau pour détacher les nouilles. Ne se congèle pas.', 4, 15, 10, array['plat', 'poele']::text[]),
  ('curry-haricots-rouges-patate-douce', 'Curry de haricots rouges et patate douce', 'Un curry doux et épais : des cubes de patate douce et des haricots rouges mijotés dans une sauce tomate au lait de coco, servis avec du riz. Économique, nourrissant, et encore meilleur réchauffé.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux avec un filet d''eau.', 4, 15, 30, array['plat', 'mijote', 'economique', 'batch-cooking']::text[]),
  ('soupe-paysanne-haricots-blancs', 'Soupe paysanne aux haricots blancs et au chou', 'Une soupe épaisse et rustique : chou vert, poireau, carottes et pommes de terre mijotés avec des haricots blancs, à la façon d''une garbure. Un repas complet pour les soirs froids, en une seule casserole.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Elle épaissit en refroidissant : ajouter un peu d''eau en réchauffant.', 6, 20, 45, array['soupe', 'mijote', 'economique', 'batch-cooking']::text[]),
  ('boulettes-lentilles-sauce-tomate', 'Boulettes de lentilles à la sauce tomate', 'Des boulettes moelleuses de lentilles vertes, d''oignon et de persil, dorées à la poêle puis mijotées dans une sauce tomate, servies avec des spaghetti. Le plat qui fait aimer les lentilles à toute la famille.', 'Les boulettes en sauce se gardent 3 jours au réfrigérateur et se congèlent 3 mois. Réchauffer à feu doux, à couvert.', 4, 30, 45, array['plat', 'poele', 'economique']::text[]),
  ('quesadillas-haricots-rouges', 'Quesadillas aux haricots rouges et au cheddar', 'Des tortillas croustillantes garnies de haricots rouges écrasés aux épices, de maïs, de poivron et de cheddar fondu, dorées à la poêle. Un dîner rapide et convivial, à tremper dans une sauce au yaourt.', 'La garniture se garde 3 jours au réfrigérateur. Les quesadillas se dorent au moment de servir ; cuites, elles se réchauffent 2 minutes par face à la poêle.', 4, 15, 15, array['plat', 'poele', 'economique']::text[]),
  ('gnocchis-tomate-mozzarella', 'Gnocchis gratinés à la tomate et à la mozzarella', 'Des gnocchis rissolés puis gratinés au four dans une sauce tomate au basilic, sous une couche de mozzarella filante. Un plat réconfortant prêt en vingt-cinq minutes, sans précuire les gnocchis.', 'Se garde 2 jours au réfrigérateur. Réchauffer 10 minutes au four à 180 °C. Ne se congèle pas.', 4, 10, 20, array['plat', 'four', 'economique']::text[]),
  ('pates-pois-chiches', 'Pâtes aux pois chiches, tomate et romarin', 'Un classique de la cuisine familiale italienne : des petites pâtes cuites avec des pois chiches dans un bouillon à la tomate, dont une partie est écrasée pour rendre le plat crémeux. Simple, économique et très rassasiant.', 'Se garde 3 jours au réfrigérateur. Les pâtes absorbent le liquide : réchauffer à feu doux avec un peu d''eau. Ne se congèle pas bien.', 4, 10, 25, array['plat', 'economique', 'batch-cooking']::text[]),
  ('harira', 'Harira aux lentilles et pois chiches', 'Une soupe épaisse d''inspiration marocaine : lentilles, pois chiches et tomate parfumés au cumin, à la cannelle et à la coriandre, relevés d''un trait de citron. Un repas complet dans un bol.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Elle épaissit en refroidissant : ajouter un peu d''eau en réchauffant.', 6, 20, 45, array['soupe', 'mijote', 'economique', 'batch-cooking']::text[]),
  ('cassoulet-express', 'Cassoulet express aux saucisses', 'Toute la gourmandise du cassoulet en une heure : des saucisses dorées et des haricots blancs mijotés dans une sauce tomate au thym, gratinés sous une chapelure croustillante. Un plat d''hiver qui se réchauffe très bien.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Réchauffer au four à 180 °C, couvert, avec un peu d''eau.', 4, 20, 45, array['plat', 'mijote', 'four', 'batch-cooking']::text[]),
  ('dinde-poivrons-paprika', 'Sauté de dinde aux poivrons et au paprika', 'Des lanières de dinde saisies puis mijotées avec des poivrons, de l''oignon et de la tomate dans une sauce au paprika, adoucie d''un peu de crème. Un plat coloré et rapide, servi avec du riz.', 'Se garde 3 jours au réfrigérateur et se congèle 2 mois, sans le riz. Réchauffer à feu doux à couvert.', 4, 15, 25, array['plat', 'poele']::text[]),
  ('porc-aigre-doux-ananas', 'Porc à l''aigre-douce et à l''ananas', 'Des morceaux de filet de porc dorés, avec poivron, oignon et ananas, dans une sauce aigre-douce brillante au ketchup, au vinaigre et à la sauce soja. Un plat de restaurant chinois fait maison, servi avec du riz thaï.', 'Se garde 3 jours au réfrigérateur. Réchauffer à la poêle avec un filet d''eau. Se congèle 2 mois, sans le riz.', 4, 20, 20, array['plat', 'poele']::text[]),
  ('boeuf-carottes', 'Bœuf carottes', 'Le plat mijoté de nos grands-mères : du bœuf cuit très lentement avec des carottes, de l''oignon, du vin blanc et du thym, jusqu''à devenir fondant à la cuillère. Il se prépare la veille et n''en est que meilleur.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Encore meilleur réchauffé le lendemain, à feu doux et à couvert.', 6, 25, 150, array['plat', 'mijote', 'batch-cooking']::text[]),
  ('moussaka', 'Moussaka', 'Le gratin grec : des tranches d''aubergine rôties, une sauce à la viande hachée parfumée à la cannelle, et une béchamel dorée au fromage. Long à préparer mais idéal à l''avance, il nourrit toute une tablée.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois, en parts. Réchauffer 25 minutes au four à 170 °C, couvert.', 6, 40, 75, array['plat', 'four', 'batch-cooking']::text[]),
  ('navarin-agneau', 'Navarin d''agneau aux légumes', 'Un ragoût d''agneau mijoté avec carottes, navets, pommes de terre et petits pois, dans une sauce légère à la tomate et au thym. Le plat du printemps, qui se cuisine aussi toute l''année avec des petits pois surgelés.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois. Réchauffer à feu doux à couvert ; les pommes de terre se congèlent moins bien.', 6, 30, 105, array['plat', 'mijote', 'batch-cooking']::text[]),
  ('veau-marengo', 'Sauté de veau Marengo', 'Des morceaux de veau mijotés avec des tomates, des champignons, des oignons et du vin blanc, à la façon d''un sauté Marengo. Une viande tendre dans une sauce parfumée, servie avec des tagliatelles ou du riz.', 'Le sauté se garde 3 jours au réfrigérateur et se congèle 3 mois, sans les pâtes. Réchauffer à feu doux à couvert.', 6, 25, 95, array['plat', 'mijote', 'batch-cooking']::text[]),
  ('salade-poulet-mangue-avocat', 'Salade de poulet, mangue et avocat', 'Une grande salade fraîche et complète : du poulet poêlé, de la mangue, de l''avocat, du concombre et du riz, avec une vinaigrette au citron vert et à la sauce soja. Parfaite pour les soirs chauds.', 'Le poulet et le riz se gardent 2 jours au réfrigérateur. Couper l''avocat et assaisonner au dernier moment.', 4, 25, 15, array['salade', 'poele']::text[]),
  ('pizzas-tortilla-jambon-champignons', 'Pizzas tortilla au jambon et aux champignons', 'Des pizzas ultra-fines sur tortillas, garnies de sauce tomate, de jambon, de champignons et de mozzarella, croustillantes en dix minutes de four. Le dîner du vendredi soir, sans pâte à préparer.', 'À déguster tout de suite. Les restes se gardent 1 jour au réfrigérateur et se réchauffent 4 minutes à la poêle, à couvert.', 4, 15, 10, array['plat', 'four', 'economique']::text[]),
  ('cake-sale-jambon-olives', 'Cake salé au jambon et aux olives', 'Un cake moelleux au jambon, aux olives et à l''emmental, qui se coupe en tranches pour un dîner avec une salade, un pique-nique ou l''apéritif. Il se prépare en quinze minutes et se garde plusieurs jours.', 'Se garde 4 jours au réfrigérateur, emballé. Se congèle 2 mois, en tranches. Se mange froid ou tiédi 10 secondes au micro-ondes.', 6, 15, 45, array['plat', 'four', 'batch-cooking']::text[]),
  ('flan-patissier', 'Flan pâtissier', 'Le flan de boulangerie à la vanille, crémeux et ferme à la fois, sur une pâte brisée croustillante. Il demande un peu de patience au réfrigérateur, mais aucune technique compliquée.', 'Se garde 3 jours au réfrigérateur, couvert. Ne se congèle pas.', 8, 20, 50, array['dessert', 'four']::text[]),
  ('compote-pommes-poires', 'Compote pommes et poires maison', 'Une compote douce, sans sucre ajouté, de pommes et de poires cuites avec une pointe de cannelle. Le dessert le plus simple qui soit, qui sauve aussi les fruits un peu trop mûrs.', 'Se garde 5 jours au réfrigérateur dans un bocal fermé et se congèle 3 mois, en portions.', 6, 15, 25, array['dessert', 'economique', 'batch-cooking']::text[]),
  ('pancakes-banane-avoine', 'Pancakes banane et flocons d''avoine', 'Des petits pancakes moelleux faits de banane écrasée, d''œufs et de flocons d''avoine, sans farine ni sucre ajouté. Un petit-déjeuner rapide qui utilise les bananes trop mûres.', 'Se gardent 2 jours au réfrigérateur et se congèlent 2 mois. Les réchauffer 1 minute par face à la poêle ou au grille-pain.', 2, 10, 10, array['petit-dejeuner', 'poele', 'economique']::text[]),
  ('tartines-avocat-oeuf', 'Tartines d''avocat et œuf mollet', 'Du pain grillé, un avocat écrasé au citron et une pointe de piment, et un œuf mollet au jaune coulant. Un petit-déjeuner salé qui fait aussi un déjeuner rapide.', 'À préparer au moment de les manger : l''avocat noircit et le pain ramollit.', 2, 10, 6, array['petit-dejeuner', 'economique']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

