  ('tartines-avocat-oeuf', 'poivre', null, null, true, null, 7)
) as v(recipe, ingredient, qty, unit, optional, note, pos)
join public.recipes r on r.slug = v.recipe
join public.ingredients i on i.slug = v.ingredient;

