  ('cassoulet-express', 7, 'Couper les saucisses en tronçons et les enfoncer dans les haricots. Laisser mijoter 20 minutes à feu doux, à couvert.'),
  ('cassoulet-express', 8, 'Préchauffer le four à 200 °C.'),
  ('cassoulet-express', 9, 'Retirer le laurier, parsemer de chapelure et enfourner 20 minutes à découvert, jusqu''à ce que le dessus soit doré et croustillant.'),
  ('dinde-poivrons-paprika', 1, 'Couper les escalopes de dinde en lanières. Épépiner les poivrons et les couper en lanières. Éplucher et émincer l''oignon et l''ail.'),
  ('dinde-poivrons-paprika', 2, 'Faire chauffer une cuillerée d''huile dans une sauteuse à feu vif et y saisir la dinde 3 à 4 minutes, jusqu''à ce qu''elle soit dorée. La réserver sur une assiette.'),
  ('dinde-poivrons-paprika', 3, 'Baisser le feu à moyen, ajouter le reste de l''huile et faire revenir l''oignon et les poivrons 8 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('dinde-poivrons-paprika', 4, 'Ajouter l''ail et le paprika, et remuer 1 minute.'),
  ('dinde-poivrons-paprika', 5, 'Verser la tomate concassée, saler, poivrer et laisser frémir 5 minutes.'),
  ('dinde-poivrons-paprika', 6, 'Remettre la dinde avec son jus et cuire encore 5 minutes à feu doux.'),
  ('dinde-poivrons-paprika', 7, 'Pendant ce temps, cuire le riz dans une casserole d''eau salée bouillante le temps indiqué sur le paquet, puis l''égoutter.'),
  ('dinde-poivrons-paprika', 8, 'Hors du feu, incorporer la crème fraîche.'),
  ('dinde-poivrons-paprika', 9, 'Servir sur le riz, parsemé de persil ciselé.'),
  ('porc-aigre-doux-ananas', 1, 'Couper le porc en cubes d''environ 2 cm et les rouler dans la moitié de la fécule.'),
  ('porc-aigre-doux-ananas', 2, 'Éplucher l''ananas et le couper en morceaux. Épépiner les poivrons et les couper en carrés. Éplucher l''oignon et le couper en quartiers ; émincer l''ail.'),
  ('porc-aigre-doux-ananas', 3, 'Dans un bol, mélanger le ketchup, le vinaigre, la sauce soja, le sucre roux, le reste de la fécule et un demi-verre d''eau : c''est la sauce.'),
  ('porc-aigre-doux-ananas', 4, 'Cuire le riz dans une casserole d''eau salée bouillante le temps indiqué sur le paquet, puis l''égoutter.'),
  ('porc-aigre-doux-ananas', 5, 'Faire chauffer l''huile dans un wok ou une grande poêle à feu vif et y dorer le porc 5 à 6 minutes, jusqu''à ce qu''il soit cuit et doré. Le réserver.'),
  ('porc-aigre-doux-ananas', 6, 'Dans le même wok, faire sauter l''oignon et les poivrons 4 minutes : ils doivent rester un peu croquants.'),
  ('porc-aigre-doux-ananas', 7, 'Ajouter l''ail et l''ananas et faire sauter 1 minute.'),
  ('porc-aigre-doux-ananas', 8, 'Remettre le porc, verser la sauce et remuer 1 à 2 minutes, jusqu''à ce qu''elle épaississe et nappe la viande.'),
  ('porc-aigre-doux-ananas', 9, 'Servir aussitôt avec le riz.'),
  ('boeuf-carottes', 1, 'Couper la viande en gros cubes si elle ne l''est pas déjà, et l''éponger avec du papier absorbant.'),
  ('boeuf-carottes', 2, 'Éplucher les carottes et les couper en rondelles épaisses. Éplucher et émincer les oignons et l''ail.'),
  ('boeuf-carottes', 3, 'Faire chauffer l''huile dans une cocotte à feu vif et y dorer la viande en plusieurs fois, 5 minutes par fournée, jusqu''à ce qu''elle soit bien colorée. La réserver.'),
  ('boeuf-carottes', 4, 'Baisser le feu à moyen et faire revenir les oignons 5 minutes dans la cocotte.'),
  ('boeuf-carottes', 5, 'Remettre la viande, saupoudrer de farine et remuer 1 minute pour la faire légèrement roussir.'),
  ('boeuf-carottes', 6, 'Verser le vin blanc en grattant le fond de la cocotte, puis ajouter de l''eau à hauteur et émietter le cube de bouillon.'),
  ('boeuf-carottes', 7, 'Ajouter l''ail, le thym et le laurier. Saler, poivrer et porter à frémissement.'),
  ('boeuf-carottes', 8, 'Couvrir et laisser mijoter 1 heure à feu très doux.'),
  ('boeuf-carottes', 9, 'Ajouter les carottes et poursuivre 1 heure à 1 heure 30, jusqu''à ce que la viande se défasse à la fourchette.'),
  ('boeuf-carottes', 10, 'Retirer le laurier et servir parsemé de persil ciselé.'),
  ('moussaka', 1, 'Préchauffer le four à 220 °C.'),
  ('moussaka', 2, 'Couper les aubergines en tranches d''environ 1 cm, les badigeonner d''huile sur les deux faces et les étaler sur deux plaques. Saler.'),
  ('moussaka', 3, 'Rôtir les aubergines 20 minutes en les retournant à mi-cuisson, jusqu''à ce qu''elles soient tendres et dorées.'),
  ('moussaka', 4, 'Pendant ce temps, éplucher et émincer l''oignon et l''ail.'),
  ('moussaka', 5, 'Faire revenir l''oignon dans une sauteuse avec un filet d''huile à feu moyen 5 minutes, puis ajouter la viande et l''ail. Cuire 5 minutes en émiettant la viande à la spatule.'),
  ('moussaka', 6, 'Ajouter la tomate concassée, le concentré et la cannelle. Saler, poivrer et laisser mijoter 15 minutes à feu doux, jusqu''à ce que la sauce soit épaisse.'),
  ('moussaka', 7, 'Pour la béchamel, faire fondre le beurre dans une casserole à feu moyen, ajouter la farine et remuer 1 minute.'),
  ('moussaka', 8, 'Verser le lait petit à petit en fouettant, et cuire 5 minutes en fouettant jusqu''à ce que la sauce épaississe. Saler, ajouter de la muscade et la moitié du parmesan.'),
  ('moussaka', 9, 'Baisser le four à 180 °C.'),
  ('moussaka', 10, 'Dans un plat à gratin, alterner une couche d''aubergines, la sauce à la viande, puis le reste des aubergines.'),
  ('moussaka', 11, 'Napper de béchamel et parsemer du reste de parmesan.'),
  ('moussaka', 12, 'Enfourner 35 minutes, jusqu''à ce que le dessus soit bien doré, puis laisser reposer 15 minutes avant de couper.'),
  ('navarin-agneau', 1, 'Éponger les morceaux d''agneau avec du papier absorbant. Éplucher et émincer l''oignon et l''ail.'),
  ('navarin-agneau', 2, 'Faire chauffer l''huile dans une cocotte à feu vif et y dorer l''agneau en plusieurs fois, 5 minutes par fournée. Le réserver.'),
  ('navarin-agneau', 3, 'Baisser le feu à moyen et faire revenir l''oignon 5 minutes dans la cocotte.'),
  ('navarin-agneau', 4, 'Remettre la viande, saupoudrer de farine et remuer 1 minute, puis ajouter le concentré de tomate et l''ail.'),
  ('navarin-agneau', 5, 'Couvrir d''eau à hauteur, émietter le cube de bouillon, ajouter le thym et le laurier. Saler, poivrer et porter à frémissement.'),
  ('navarin-agneau', 6, 'Couvrir et laisser mijoter 1 heure à feu doux.'),
  ('navarin-agneau', 7, 'Pendant ce temps, éplucher les carottes et les navets et les couper en gros morceaux. Laver les pommes de terre grenaille.'),
  ('navarin-agneau', 8, 'Ajouter les carottes, les navets et les pommes de terre dans la cocotte et poursuivre 30 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('navarin-agneau', 9, 'Ajouter les petits pois et cuire encore 10 minutes à découvert.'),
  ('navarin-agneau', 10, 'Retirer le laurier, goûter et rectifier l''assaisonnement avant de servir.'),
  ('veau-marengo', 1, 'Éponger les morceaux de veau. Éplucher et émincer les oignons et l''ail.'),
  ('veau-marengo', 2, 'Faire chauffer l''huile dans une cocotte à feu vif et y dorer le veau en plusieurs fois, 4 à 5 minutes par fournée. Le réserver.'),
  ('veau-marengo', 3, 'Baisser le feu à moyen et faire revenir les oignons 5 minutes dans la cocotte.'),
  ('veau-marengo', 4, 'Remettre la viande, saupoudrer de farine et remuer 1 minute.'),
  ('veau-marengo', 5, 'Verser le vin blanc en grattant le fond, puis ajouter la tomate concassée, le concentré, l''ail, les herbes et le laurier. Ajouter de l''eau juste à hauteur, saler et poivrer.'),
  ('veau-marengo', 6, 'Couvrir et laisser mijoter 1 heure à feu doux.'),
  ('veau-marengo', 7, 'Pendant ce temps, nettoyer les champignons et les couper en quartiers.'),
  ('veau-marengo', 8, 'Ajouter les champignons et poursuivre 20 minutes à découvert, jusqu''à ce que la viande soit tendre et la sauce nappante.'),
  ('veau-marengo', 9, 'Cuire les tagliatelles dans une grande casserole d''eau salée bouillante le temps indiqué sur le paquet, puis les égoutter.'),
  ('veau-marengo', 10, 'Retirer le laurier et servir le veau sur les tagliatelles, parsemé de persil ciselé.'),
  ('salade-poulet-mangue-avocat', 1, 'Cuire le riz dans une casserole d''eau salée bouillante le temps indiqué sur le paquet, l''égoutter et le rincer à l''eau froide.'),
  ('salade-poulet-mangue-avocat', 2, 'Faire chauffer une cuillerée d''huile de tournesol dans une poêle à feu moyen et y cuire les filets de poulet 5 à 6 minutes par face, jusqu''à ce qu''ils soient dorés et cuits à cœur. Saler et laisser tiédir.'),
  ('salade-poulet-mangue-avocat', 3, 'Éplucher la mangue et la couper en dés. Couper les avocats en deux, retirer le noyau et les couper en dés.'),
  ('salade-poulet-mangue-avocat', 4, 'Couper le concombre en demi-rondelles. Laver la salade et l''essorer.'),
  ('salade-poulet-mangue-avocat', 5, 'Dans un bol, mélanger le jus des citrons verts, la sauce soja, l''huile de sésame et le reste de l''huile de tournesol.'),
  ('salade-poulet-mangue-avocat', 6, 'Couper le poulet en lamelles.'),
  ('salade-poulet-mangue-avocat', 7, 'Dans un grand saladier, disposer la salade, le riz, le poulet, la mangue, l''avocat et le concombre.'),
  ('salade-poulet-mangue-avocat', 8, 'Arroser de vinaigrette et parsemer de coriandre ciselée et de graines de sésame.'),
  ('pizzas-tortilla-jambon-champignons', 1, 'Préchauffer le four à 220 °C.'),
  ('pizzas-tortilla-jambon-champignons', 2, 'Nettoyer les champignons et les couper en fines lamelles. Couper le jambon en morceaux et la mozzarella en dés après l''avoir égouttée.'),
  ('pizzas-tortilla-jambon-champignons', 3, 'Poser les tortillas sur deux plaques recouvertes de papier de cuisson.'),
  ('pizzas-tortilla-jambon-champignons', 4, 'Étaler une fine couche de coulis de tomate sur chaque tortilla, sans aller jusqu''au bord.'),
  ('pizzas-tortilla-jambon-champignons', 5, 'Répartir le jambon, les champignons, les olives et la mozzarella.'),
  ('pizzas-tortilla-jambon-champignons', 6, 'Parsemer d''herbes de Provence, saler légèrement, poivrer et arroser d''un filet d''huile.'),
  ('pizzas-tortilla-jambon-champignons', 7, 'Enfourner 8 à 10 minutes, jusqu''à ce que les bords soient croustillants et la mozzarella fondue.'),
  ('pizzas-tortilla-jambon-champignons', 8, 'Servir aussitôt, avec une salade verte.'),
  ('cake-sale-jambon-olives', 1, 'Préchauffer le four à 180 °C. Beurrer un moule à cake.'),
  ('cake-sale-jambon-olives', 2, 'Couper le jambon en dés et les olives en rondelles.'),
  ('cake-sale-jambon-olives', 3, 'Dans un saladier, mélanger la farine, la levure et une pincée de sel.'),
  ('cake-sale-jambon-olives', 4, 'Dans un autre bol, battre les œufs avec le lait et l''huile.'),
  ('cake-sale-jambon-olives', 5, 'Verser le mélange liquide sur la farine et mélanger juste ce qu''il faut pour obtenir une pâte lisse, sans trop travailler.'),
  ('cake-sale-jambon-olives', 6, 'Ajouter le jambon, les olives, l''emmental et les herbes, poivrer et mélanger.'),
  ('cake-sale-jambon-olives', 7, 'Verser la pâte dans le moule et enfourner 45 minutes : la lame d''un couteau doit ressortir sèche.'),
  ('cake-sale-jambon-olives', 8, 'Laisser tiédir 10 minutes avant de démouler, puis servir en tranches avec une salade verte.'),
  ('flan-patissier', 1, 'Préchauffer le four à 180 °C. Beurrer un moule à bord haut et y étaler la pâte en gardant le papier de cuisson.'),
  ('flan-patissier', 2, 'Faire chauffer le lait avec la vanille dans une casserole à feu moyen, jusqu''à frémissement.'),
  ('flan-patissier', 3, 'Dans un saladier, fouetter les œufs avec le sucre, puis ajouter la fécule et fouetter jusqu''à obtenir un mélange lisse.'),
  ('flan-patissier', 4, 'Verser le lait chaud petit à petit sur le mélange en fouettant sans arrêt.'),
  ('flan-patissier', 5, 'Reverser le tout dans la casserole et cuire à feu moyen en fouettant 2 à 3 minutes, jusqu''à ce que la crème épaississe nettement.'),
  ('flan-patissier', 6, 'Verser la crème chaude sur la pâte et lisser la surface.'),
  ('flan-patissier', 7, 'Enfourner 45 à 50 minutes, jusqu''à ce que le dessus soit bien doré par endroits.'),
  ('flan-patissier', 8, 'Laisser refroidir complètement, puis réfrigérer au moins 4 heures avant de couper : le flan doit être bien pris.'),
  ('compote-pommes-poires', 1, 'Éplucher les pommes et les poires, retirer le cœur et les couper en morceaux.'),
  ('compote-pommes-poires', 2, 'Mettre les fruits dans une casserole avec le jus du demi-citron, la cannelle, la vanille et un fond d''eau.'),
  ('compote-pommes-poires', 3, 'Porter à frémissement, puis couvrir et cuire 20 minutes à feu doux en remuant de temps en temps, jusqu''à ce que les fruits soient très tendres.'),
  ('compote-pommes-poires', 4, 'Écraser à la fourchette pour une compote rustique, ou mixer pour une compote lisse.'),
  ('compote-pommes-poires', 5, 'Laisser refroidir et servir tiède ou froide.'),
  ('pancakes-banane-avoine', 1, 'Écraser les bananes à la fourchette dans un saladier, jusqu''à obtenir une purée.'),
  ('pancakes-banane-avoine', 2, 'Ajouter les œufs, les flocons d''avoine, le lait et la cannelle, et mélanger : la pâte est épaisse.'),
  ('pancakes-banane-avoine', 3, 'Laisser reposer 5 minutes pour que les flocons gonflent.'),
  ('pancakes-banane-avoine', 4, 'Faire chauffer une poêle antiadhésive à feu moyen-doux et la graisser avec un peu d''huile étalée au papier absorbant.'),
  ('pancakes-banane-avoine', 5, 'Verser de petites louches de pâte et cuire 2 à 3 minutes, jusqu''à ce que des bulles apparaissent et que le dessous soit doré.'),
  ('pancakes-banane-avoine', 6, 'Retourner délicatement et cuire encore 1 à 2 minutes.'),
  ('pancakes-banane-avoine', 7, 'Servir chaud avec les myrtilles et un filet de sirop d''érable.'),
  ('tartines-avocat-oeuf', 1, 'Porter une petite casserole d''eau à ébullition, y plonger délicatement les œufs et les cuire 6 minutes.'),
  ('tartines-avocat-oeuf', 2, 'Les passer sous l''eau froide, puis les écaler délicatement.'),
  ('tartines-avocat-oeuf', 3, 'Pendant la cuisson, faire griller les tranches de pain.'),
  ('tartines-avocat-oeuf', 4, 'Couper l''avocat en deux, retirer le noyau et écraser la chair à la fourchette avec le jus du citron, du sel et du poivre.'),
  ('tartines-avocat-oeuf', 5, 'Étaler l''avocat sur les tartines.'),
  ('tartines-avocat-oeuf', 6, 'Couper les œufs en deux et les poser sur les tartines. Parsemer de piment et de graines de sésame, et servir aussitôt.')
) as v(recipe, pos, instruction)
join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('curry-cabillaud-coco-epinards', 'parmentier-cabillaud', 'spaghetti-sardines-citron', 'saumon-patate-douce-epinards', 'saumon-lentilles-vertes', 'cabillaud-sauce-vierge-quinoa', 'salade-thon-haricots-blancs', 'quiche-saumon-poireaux', 'pad-thai-crevettes', 'curry-haricots-rouges-patate-douce', 'soupe-paysanne-haricots-blancs', 'boulettes-lentilles-sauce-tomate', 'quesadillas-haricots-rouges', 'gnocchis-tomate-mozzarella', 'pates-pois-chiches', 'harira', 'cassoulet-express', 'dinde-poivrons-paprika', 'porc-aigre-doux-ananas', 'boeuf-carottes', 'moussaka', 'navarin-agneau', 'veau-marengo', 'salade-poulet-mangue-avocat', 'pizzas-tortilla-jambon-champignons', 'cake-sale-jambon-olives', 'flan-patissier', 'compote-pommes-poires', 'pancakes-banane-avoine', 'tartines-avocat-oeuf')) <> 349 then
    raise exception 'Lignes d''ingrédients manquantes dans le quatrième lot de recettes.';
  end if;
end;
$$;
